S = "Hakeem Force Academy"
QS = [
(S, "What is the average gestation period of a cow?", ["About 150 days", "About 283 days", "About 365 days", "About 210 days"], 1, "A cow carries her calf for about 283 days, which is roughly nine months. This is close to the human pregnancy length.", "The gestation period of a buffalo is longer, about 310 to 315 days.", [473, 3394, 3396]),
(S, "What is the capital of Ghana?", ["Lagos", "Accra", "Nairobi", "Kumasi"], 1, "Accra is the capital and largest city of Ghana, on the Gulf of Guinea coast.", "Ghana was the first sub-Saharan African country to gain independence from Britain, in 1957.", [27]),
(S, "Ghani Khan, the famous poet and philosopher, wrote mainly in which language?", ["Urdu", "Punjabi", "Pashto", "Sindhi"], 2, "Ghani Khan (1914-1996) was a well known Pashto poet, painter and philosopher from Charsadda.", "He was the son of Khan Abdul Ghaffar Khan and wrote the book The Pathans.", [94, 1246]),
(S, "A class has 1500 students and 1200 of them are boys. What is the percentage of girls?", ["25 percent", "30 percent", "15 percent", "20 percent"], 3, "Girls = 1500 - 1200 = 300. Percentage = 300 / 1500 x 100 = 20 percent.", "Boys make up the other 80 percent of this class.", [822]),
(S, "In a group, 2/3 of the people are men. What percentage of the group is women?", ["33.33 percent", "66.67 percent", "25 percent", "30 percent"], 0, "Women = 1 - 2/3 = 1/3 of the group. 1/3 x 100 = 33.33 percent.", "The fraction 1/3 equals 33.33 percent as a decimal-percent value.", [2533]),
(S, "Change into passive voice: God gives us happiness.", ["Happiness is given to us by God.", "Happiness was given to us by God.", "Happiness has been given us by God.", "We are given by God happiness."], 0, "The sentence is in the simple present tense, so the passive uses is/are plus the past participle: Happiness is given to us by God.", "In passive voice the object of the active sentence becomes the subject.", [1584]),
(S, "What is the height of a standard football goal (inside the posts, from ground to crossbar)?", ["6 feet", "10 feet", "8 feet", "12 feet"], 2, "The crossbar of a standard football goal is 8 feet (2.44 m) above the ground.", "The candidate answer of 24 inches is wrong; 24 feet is the width of the goal.", [963]),
(S, "What is the width (length between the posts) of a standard football goal?", ["24 feet", "18 feet", "30 feet", "20 feet"], 0, "The two posts of a standard football goal are 24 feet (7.32 m) apart.", "The goal height is 8 feet (2.44 m).", [215]),
(S, "The speed of a train is twice that of a car. What is the speed of the train when the car is going at 30 km/hr?", ["15 km/hr", "90 km/hr", "45 km/hr", "60 km/hr"], 3, "Train speed = 2 x 30 = 60 km/hr.", "Speed is distance divided by time, so a train at 60 km/hr covers 60 km in one hour.", [2751]),
(S, "Ali is going in the direction of west. He turns left and then turns right. In which direction is Ali going now?", ["North", "South", "East", "West"], 3, "Facing west, a left turn points him south. Then a right turn from south points him west again.", "Facing west, his left is south and his right is north.", [1467]),
(S, "Who is the current Governor of Sindh (as of October 2026)?", ["Kamran Tessori", "Nehal Hashmi", "Imran Ismail", "Ishrat-ul-Ebad"], 1, "Nehal Hashmi of the PML-N took oath as Governor of Sindh on 13 March 2026.", "He replaced Kamran Khan Tessori of the MQM-P, who was governor in 2022.", [4920, 4935]),
(S, "When a man asked the Prophet (PBUH) who most deserved his good treatment, whom did the Prophet name first?", ["Father", "Mother", "Teacher", "Neighbour"], 1, "In the well known hadith the Prophet (PBUH) said \"your mother\" three times, and only then \"your father\".", "This hadith is reported in Sahih Bukhari and Sahih Muslim.", [4811]),
(S, "Who said that the life of the Prophet Muhammad (PBUH) is the best example?", ["Allah, in the Holy Quran", "Hazrat Khadija (RA)", "Hazrat Ali (RA)", "Abu Talib"], 0, "Allah says in Surah Al-Ahzab (33:21) that the Messenger of Allah is an excellent example for those who hope in Allah.", "The Quran also describes the Prophet's character as of the highest standard in Surah Al-Qalam (68:4).", [5017, 5019]),
(S, "If Ali is greater than Usama, then Usama is ___ than Ali.", ["smaller", "taller", "older", "greater"], 0, "Ali being greater means Usama is lesser, that is smaller, than Ali.", "Greater and smaller (or less) are opposite comparisons.", [2023]),
(S, "Which is the greatest number among 5, 4, 6, 9, 7 and 3?", ["7", "6", "9", "5"], 2, "Comparing all the numbers, 9 is larger than 5, 4, 6, 7 and 3.", "The smallest number in this list is 3.", [1149]),
(S, "The Karen ethnic group lives mainly in which countries?", ["Myanmar and Thailand", "Nepal and India", "Cambodia and Vietnam", "Malaysia and Indonesia"], 0, "The Karen people live mostly in Myanmar (Burma), especially Kayin State, and in western Thailand along the border.", "Karen rebels in Myanmar have fought the government since 1949.", [2728]),
(S, "In which city is the Nuclear Suppliers Group (NSG) based?", ["Geneva", "New York", "The Hague", "Vienna"], 3, "The NSG has no permanent headquarters, but its secretariat and point of contact work from Vienna, Austria, beside the IAEA.", "The NSG was formed in 1974 after India's first nuclear test.", [4183]),
]
